problem.solution:
// Solution with augmented operators
public class Main {
  public static void main(String[] args) {
    double bill = 50;
    double tip = bill * 0.1;
    bill += tip;

    int wallet = 100;
    wallet -= 20;

    System.out.println("Total bill: " + bill);
    System.out.println("Wallet: " + wallet);
  }
}
